target = pathlib.Path(sys.argv[2])
if target.parent.is_symlink() or target.is_symlink():
    raise SystemExit('Refusing a symbolic-link source state path')
target.parent.mkdir(mode=0o700, exist_ok=True)
user = os.environ.get('SUDO_USER')
uid, gid = (pwd.getpwnam(user).pw_uid, pwd.getpwnam(user).pw_gid) if user else (os.getuid(), os.getgid())
fd, temporary = tempfile.mkstemp(prefix='.addon-sources-', dir=target.parent)
try:
    with os.fdopen(fd, 'wb') as out:
        out.write(pathlib.Path(sys.argv[1]).read_bytes())
        out.flush()
        os.fsync(out.fileno())
    os.chmod(temporary, 0o600)
    os.chown(temporary, uid, gid)
    os.chown(target.parent, uid, gid)
    os.replace(temporary, target)
finally:
    if os.path.exists(temporary):
